/* eslint-disable no-use-before-define */
import React from 'react';
import { MenuButton, Menu, Icon } from '@alifd/next';
import { Types, parseData, ContentType } from '@alifd/adaptor-helper';

const createDataSouce = (list, keys = { selected: [], expanded: {} }, level = 0, prefix='') => {
    const array = [];
    let group = [];
    let grouping = false;
    let index = 0;

    list.forEach((item) => {
        switch(item.type) {
            // eslint-disable-next-line no-case-declarations
            case 'node':
                const key = `${prefix || level }-${index++}`;

                if (item.children && item.children.length > 0) {
                    item.children = createDataSouce(item.children, keys, level + 1, key);
                }

                if (grouping) {
                    group.push({
                        ...item,
                        key,
                    });
                } else {
                    array.push({
                        ...item,
                        key
                    });
                }

                if (item.state === 'active') {
                    if (item.children && item.children.length > 0) {
                        keys.expanded.push(key);
                    } else {
                        keys.selected.push(key);
                    }
                }

                return;
            case 'comment':
                if (group.length > 0) {
                    array.push({
                        type: 'group',
                        value: grouping,
                        children: group,
                        key: `${prefix || level }-${index++}`
                    });
                    group = [];
                }
                grouping = item.value;
                return;
            case 'divider':
                if (group.length > 0) {
                    array.push({
                        type: 'group',
                        value: grouping,
                        children: group,
                        key: `${prefix || level }-${index++}`
                    });
                    group = [];
                }
                grouping = false;
                array.push({
                    type: 'divider',
                    key: `${prefix || level }-${index++}`,
                });
                return;
            default: return;
        }
    });

    if (group.length > 0) {
        array.push({
            type: 'group',
            value: grouping,
            children: group,
            key: `${prefix || level }-${index++}`
        });
        group = [];
    }

    return array;
};

const createMenuItem = (item) => {
    if (item.children.length > 0) {
        return (
            <Menu.SubMenu key={item.key} disabled={item.state === 'disabled'} label={item.value ? item.value.filter(({ type }) => type === ContentType.text).map(({ value }) => value).join('') : ''}>
                {createContents(item.children)}
            </Menu.SubMenu>
        );
    }

    return <Menu.Item key={item.key} checked={item.state === 'active'} disabled={item.state === 'disabled'} children={item.value.map(({ type, value }, index) => type === 'icon' ? <Icon key={`icon_${index}`} type={value} size="small" style={{ marginRight: '4px' }} /> : value)} />;
};

const createContents = (array = []) => {

    return array.map((item) => {
        if (item.type === 'group' && item.children.length > 0) {
            return <Menu.Group key={item.key} label={item.value}>{item.children.map(it => createMenuItem(it))}</Menu.Group>;
        }

        if (item.type === 'divider') {
            return <Menu.Divider key={item.key}/>;
        }

        return createMenuItem(item);
    });
};

export default {
    name: 'MenuButton',
    shape: ['normal', 'text', 'ghost'],
    editor: (shape = 'normal') => ({
        props: [{
            name: 'level',
            type: Types.enum,
            options: shape === 'text' ? ['normal', 'primary'] : shape === 'ghost' ? ['light', 'dark'] : ['normal', 'primary', 'secondary'],
            default: shape === 'ghost' ? 'light' : 'normal',
        }, {
            name: 'size',
            type: Types.enum,
            options: ['large', 'medium', 'small'],
            default: 'medium'
        }],
        data: {
            icon: true,
            active: true,
            disable: true,
            default: 'Edit Document\n\tUndo\n\t*Redo\n\tCut\n\tCopy\n\tPaste'
        }
    }),
    adaptor: ({ shape, level, size, data, ...others}) => {
        const list = parseData(data, { parseContent: true });
        const buttonItem = list[0] ? list[0] : { value: []};

        if (buttonItem.type !== 'node') return null;

        const keys = { selected: [], expanded: [] };
        const dataSouce = createDataSouce(list[0] ? list[0].children : [], keys);

        const label = buttonItem.value.map(({ type, value}) => {
            if (type === 'icon') return <Icon type={value} />;
            return value;
        });

        return (
            <MenuButton
                {...others}
                size={size}
                disabled={buttonItem.state === 'disabled'}
                visible={buttonItem.state === 'active'}
                type={shape === 'ghost' ? 'normal' : level}
                popupProps={{ needAdjust: false }}
                popupContainer={node => node}
                ghost={shape === 'ghost' ? level : false}
                selectMode="multiple"
                text={shape === 'text'}
                menuProps={{ openKeys: keys.expanded, style: { textAlign: 'left' } }}
                selectedKeys={keys.selected}
                label={label}
            >
                {createContents(dataSouce)}
            </MenuButton>
        );
    },
    demoOptions: (demo) => {
        const { node = { props: {} } } = demo;
        const { level, data } = node.props;
        if (data.indexOf('*') === 0) {
            demo = {
                ...demo,
                height: 250
            };
        }

        if (level === 'dark') {
            demo = {
                ...demo,
                background: '#333'
            };
        } else if(level === 'light') {
            demo = {
                ...demo,
                background: 'rgb(235, 236, 240)',
            };
        }

        return demo;
    }
};

